/**
 * The whole database schema. Tables for later milestones are defined up front so
 * feature work adds logic rather than migrations.
 *
 * Conventions
 * - Primary keys are UUIDv7 generated by the application (see lib/ids.ts), except
 *   `assets.id`, which is a random UUIDv4 because it appears in unauthenticated URLs.
 * - Enumerations are text columns typed with `$type`, not Postgres enums.
 * - `*_key` columns hold text normalized by lib/text.ts `matchKey` (lowercase, no
 *   diacritics or punctuation) and carry the trigram indexes used for search.
 * - Timestamps are `timestamptz`.
 */
import {
  bigint,
  boolean,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  real,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core'
import { sql } from 'drizzle-orm'

const id = () => uuid('id').primaryKey()
const at = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' })
const createdAt = () => at('created_at').notNull().defaultNow()
const updatedAt = () => at('updated_at').notNull().defaultNow()
const textArray = (name: string) => text(name).array().notNull().default(sql`'{}'::text[]`)

export type UserRole = 'admin' | 'member'
export type CatalogEntityType = 'artist' | 'album' | 'release' | 'recording'
export type LikeEntityType = 'recording' | 'album' | 'artist'
export type LibraryRootMode = 'read_only' | 'managed'
export type MatchStatus = 'pending' | 'matched' | 'review' | 'unmatched'
export type MatchSource = 'tags' | 'tags-mbid' | 'search' | 'acoustid' | 'manual'
export type ImportKind = 'upload' | 'inbox' | 'acquisition'
export type ImportStatus = 'receiving' | 'processing' | 'completed' | 'failed'
export type ImportStep = 'extracting' | 'moving' | 'identifying' | 'filing'

/** Normalized tags read from a file. Everything is optional; files are often badly tagged. */
export type FileTags = {
  title?: string
  artist?: string
  artists?: string[]
  album?: string
  albumArtist?: string
  date?: string
  year?: number
  track?: number
  trackTotal?: number
  disc?: number
  discTotal?: number
  genres?: string[]
  compilation?: boolean
  isrcs?: string[]
  barcode?: string
  label?: string
  catalogNumber?: string
  mbRecordingId?: string
  mbTrackId?: string
  mbReleaseId?: string
  mbReleaseGroupId?: string
  mbArtistIds?: string[]
  mbAlbumArtistIds?: string[]
  hasLyrics?: boolean
}

// ---------------------------------------------------------------------------
// Users and auth
// ---------------------------------------------------------------------------

export const users = pgTable('users', {
  id: id(),
  username: text('username').notNull(),
  /** Lowercased username; the unique identity. */
  usernameKey: text('username_key').notNull(),
  displayName: text('display_name'),
  passwordHash: text('password_hash').notNull(),
  role: text('role').$type<UserRole>().notNull().default('member'),
  canUpload: boolean('can_upload').notNull().default(false),
  canAcquire: boolean('can_acquire').notNull().default(false),
  /** UserSettings from @squirmy/contracts, plus encrypted per-user secrets under `secrets`. */
  settings: jsonb('settings').$type<Record<string, unknown>>().notNull().default({}),
  disabledAt: at('disabled_at'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [uniqueIndex('users_username_key').on(t.usernameKey)])

export const authSessions = pgTable('auth_sessions', {
  id: id(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  /** SHA-256 of the opaque token, hex. The token itself is never stored. */
  tokenHash: text('token_hash').notNull(),
  deviceId: text('device_id'),
  clientKind: text('client_kind').notNull().default('other'),
  userAgent: text('user_agent'),
  createdAt: createdAt(),
  lastSeenAt: at('last_seen_at').notNull().defaultNow(),
  expiresAt: at('expires_at').notNull(),
}, (t) => [
  uniqueIndex('auth_sessions_token_hash').on(t.tokenHash),
  index('auth_sessions_user').on(t.userId),
])

export const invites = pgTable('invites', {
  id: id(),
  code: text('code').notNull(),
  role: text('role').$type<UserRole>().notNull().default('member'),
  canUpload: boolean('can_upload').notNull().default(false),
  canAcquire: boolean('can_acquire').notNull().default(false),
  createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
  expiresAt: at('expires_at'),
  usedBy: uuid('used_by').references(() => users.id, { onDelete: 'set null' }),
  usedAt: at('used_at'),
  createdAt: createdAt(),
}, (t) => [uniqueIndex('invites_code').on(t.code)])

/** Credentials for Subsonic clients: one generated secret per client. */
export const appPasswords = pgTable('app_passwords', {
  id: id(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  /** AES-GCM ciphertext. Subsonic token auth needs the clear text to verify md5(secret + salt). */
  secretEncrypted: text('secret_encrypted').notNull(),
  /** SHA-256 of the secret, for `apiKey` lookups that carry no username. */
  keyHash: text('key_hash').notNull(),
  createdAt: createdAt(),
  lastUsedAt: at('last_used_at'),
}, (t) => [
  uniqueIndex('app_passwords_key_hash').on(t.keyHash),
  index('app_passwords_user').on(t.userId),
])

/** Installs a user has signed in from. Presence (connected or not) lives in memory. */
export const devices = pgTable('devices', {
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  id: text('id').notNull(),
  name: text('name').notNull(),
  kind: text('kind').notNull().default('other'),
  createdAt: createdAt(),
  lastSeenAt: at('last_seen_at').notNull().defaultNow(),
}, (t) => [primaryKey({ columns: [t.userId, t.id] })])

/** Operator settings and encrypted secrets, one row per key. */
export const serverSettings = pgTable('server_settings', {
  key: text('key').primaryKey(),
  value: jsonb('value').$type<unknown>().notNull(),
  updatedAt: updatedAt(),
})

// ---------------------------------------------------------------------------
// Catalog: a lazy cache of MusicBrainz plus local-only rows built from file tags.
// `mbid` is null for local-only rows. `detail_level`: 0 stub (from a search result),
// 1 basic (enough to render a summary), 2 full (track lists / discography fetched).
// `merged_into_id` redirects a row that lost a merge.
// ---------------------------------------------------------------------------

export const artists = pgTable('artists', {
  id: id(),
  mbid: uuid('mbid'),
  name: text('name').notNull(),
  sortName: text('sort_name'),
  disambiguation: text('disambiguation'),
  kind: text('kind'),
  country: text('country'),
  nameKey: text('name_key').notNull(),
  genres: textArray('genres'),
  imageAssetId: uuid('image_asset_id'),
  bio: text('bio'),
  bioSource: text('bio_source'),
  bioUrl: text('bio_url'),
  detailLevel: smallint('detail_level').notNull().default(0),
  fetchedAt: at('fetched_at'),
  mergedIntoId: uuid('merged_into_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  uniqueIndex('artists_mbid').on(t.mbid),
  index('artists_name_key_trgm').using('gin', t.nameKey.op('gin_trgm_ops')),
  index('artists_name_key').on(t.nameKey),
  // Prefix search (modules/search): byte order, so a range scan finds every name starting with the query.
  index('artists_name_key_prefix').on(sql`${t.nameKey} collate "C"`),
  index('artists_name_sort').on(sql`regexp_replace(${t.nameKey}, '^(the|a|an) ', '')`, t.id),
])

/** An album is a MusicBrainz release group: the abstract album across all its editions. */
export const albums = pgTable('albums', {
  id: id(),
  mbid: uuid('mbid'),
  title: text('title').notNull(),
  /** Display string for the credited artists. */
  artistCredit: text('artist_credit').notNull(),
  primaryArtistId: uuid('primary_artist_id').references(() => artists.id, { onDelete: 'set null' }),
  /** album | ep | single | compilation | live | soundtrack | other */
  type: text('type').notNull().default('album'),
  secondaryTypes: textArray('secondary_types'),
  /** YYYY, YYYY-MM or YYYY-MM-DD, as precise as known. */
  releaseDate: text('release_date'),
  year: integer('year'),
  titleKey: text('title_key').notNull(),
  /** matchKey(artistCredit) + '|' + matchKey(title); used to dedupe and to match search results. */
  matchKey: text('match_key').notNull(),
  genres: textArray('genres'),
  description: text('description'),
  descriptionSource: text('description_source'),
  artworkAssetId: uuid('artwork_asset_id'),
  /** The edition whose track list the album page shows. */
  canonicalReleaseId: uuid('canonical_release_id'),
  detailLevel: smallint('detail_level').notNull().default(0),
  fetchedAt: at('fetched_at'),
  /** When enrichment last finished the extras owned albums get: stored cover, description, external ids, lyrics. */
  enrichedAt: at('enriched_at'),
  mergedIntoId: uuid('merged_into_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  uniqueIndex('albums_mbid').on(t.mbid),
  index('albums_title_key_trgm').using('gin', t.titleKey.op('gin_trgm_ops')),
  index('albums_match_key').on(t.matchKey),
  // Search (modules/search): fuzzy "artist title" queries, and title prefixes in byte order.
  index('albums_match_key_trgm').using('gin', t.matchKey.op('gin_trgm_ops')),
  index('albums_title_key_prefix').on(sql`${t.titleKey} collate "C"`),
  index('albums_primary_artist').on(t.primaryArtistId),
  // Library orderings (modules/catalog/library.ts). The expressions are `sortKey` over the
  // stored match keys and must stay identical to `sortKeys` in modules/catalog/sql.ts.
  index('albums_title_sort').on(sql`regexp_replace(${t.titleKey}, '^(the|a|an) ', '')`, t.id),
  index('albums_artist_sort').on(
    sql`regexp_replace(split_part(${t.matchKey}, '|', 1), '^(the|a|an) ', '')`,
    sql`regexp_replace(${t.titleKey}, '^(the|a|an) ', '')`,
    t.id,
  ),
  index('albums_year_sort').on(sql`coalesce(${t.year}, 0) desc`, sql`regexp_replace(${t.titleKey}, '^(the|a|an) ', '')`, t.id),
])

export const albumArtists = pgTable('album_artists', {
  albumId: uuid('album_id').notNull().references(() => albums.id, { onDelete: 'cascade' }),
  position: smallint('position').notNull(),
  artistId: uuid('artist_id').notNull().references(() => artists.id, { onDelete: 'cascade' }),
  creditedName: text('credited_name').notNull(),
  joinPhrase: text('join_phrase').notNull().default(''),
}, (t) => [
  primaryKey({ columns: [t.albumId, t.position] }),
  index('album_artists_artist').on(t.artistId),
])

/** One edition of an album: a MusicBrainz release, or a local-only edition built from files. */
export const releases = pgTable('releases', {
  id: id(),
  mbid: uuid('mbid'),
  albumId: uuid('album_id').notNull().references(() => albums.id, { onDelete: 'cascade' }),
  title: text('title').notNull(),
  releaseDate: text('release_date'),
  country: text('country'),
  label: text('label'),
  catalogNumber: text('catalog_number'),
  barcode: text('barcode'),
  format: text('format'),
  status: text('status'),
  trackCount: integer('track_count').notNull().default(0),
  discCount: integer('disc_count').notNull().default(1),
  detailLevel: smallint('detail_level').notNull().default(0),
  fetchedAt: at('fetched_at'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  uniqueIndex('releases_mbid').on(t.mbid),
  index('releases_album').on(t.albumId),
  index('releases_barcode').on(t.barcode),
])

/** A recording is one performance of a song. This is what clients call a track. */
export const recordings = pgTable('recordings', {
  id: id(),
  mbid: uuid('mbid'),
  title: text('title').notNull(),
  artistCredit: text('artist_credit').notNull(),
  primaryArtistId: uuid('primary_artist_id').references(() => artists.id, { onDelete: 'set null' }),
  durationMs: integer('duration_ms'),
  isrcs: textArray('isrcs'),
  titleKey: text('title_key').notNull(),
  /** matchKey(artistCredit) + '|' + matchKey(title). */
  matchKey: text('match_key').notNull(),
  /** 0..1 relative popularity when a source provides it. */
  popularity: real('popularity'),
  explicit: boolean('explicit'),
  /**
   * An album the recording appears on, for a stub from a catalog search that has no
   * release tracks yet. Summaries use it only when no file or release track gives one.
   */
  albumHintId: uuid('album_hint_id').references(() => albums.id, { onDelete: 'set null' }),
  mergedIntoId: uuid('merged_into_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  uniqueIndex('recordings_mbid').on(t.mbid),
  index('recordings_title_key_trgm').using('gin', t.titleKey.op('gin_trgm_ops')),
  index('recordings_match_key').on(t.matchKey),
  index('recordings_match_key_trgm').using('gin', t.matchKey.op('gin_trgm_ops')),
  index('recordings_title_key_prefix').on(sql`${t.titleKey} collate "C"`),
  index('recordings_album_hint').on(t.albumHintId),
  index('recordings_isrcs').using('gin', t.isrcs),
  index('recordings_primary_artist').on(t.primaryArtistId),
  index('recordings_title_sort').on(
    sql`regexp_replace(${t.titleKey}, '^(the|a|an) ', '')`,
    sql`regexp_replace(split_part(${t.matchKey}, '|', 1), '^(the|a|an) ', '')`,
    t.id,
  ),
  index('recordings_artist_sort').on(
    sql`regexp_replace(split_part(${t.matchKey}, '|', 1), '^(the|a|an) ', '')`,
    sql`regexp_replace(${t.titleKey}, '^(the|a|an) ', '')`,
    t.id,
  ),
])

export const recordingArtists = pgTable('recording_artists', {
  recordingId: uuid('recording_id').notNull().references(() => recordings.id, { onDelete: 'cascade' }),
  position: smallint('position').notNull(),
  artistId: uuid('artist_id').notNull().references(() => artists.id, { onDelete: 'cascade' }),
  creditedName: text('credited_name').notNull(),
  joinPhrase: text('join_phrase').notNull().default(''),
}, (t) => [
  primaryKey({ columns: [t.recordingId, t.position] }),
  index('recording_artists_artist').on(t.artistId),
])

export const releaseTracks = pgTable('release_tracks', {
  id: id(),
  /** MusicBrainz track id (a recording's position on one release). */
  mbid: uuid('mbid'),
  releaseId: uuid('release_id').notNull().references(() => releases.id, { onDelete: 'cascade' }),
  disc: smallint('disc').notNull().default(1),
  position: smallint('position').notNull(),
  recordingId: uuid('recording_id').notNull().references(() => recordings.id, { onDelete: 'cascade' }),
  title: text('title').notNull(),
  artistCredit: text('artist_credit'),
  durationMs: integer('duration_ms'),
  discTitle: text('disc_title'),
}, (t) => [
  uniqueIndex('release_tracks_position').on(t.releaseId, t.disc, t.position),
  index('release_tracks_recording').on(t.recordingId),
])

/** Ids of our catalog rows in other services: deezer, wikidata, discogs, spotify, isni… */
export const externalIds = pgTable('external_ids', {
  provider: text('provider').notNull(),
  entityType: text('entity_type').$type<CatalogEntityType>().notNull(),
  externalId: text('external_id').notNull(),
  entityId: uuid('entity_id').notNull(),
  createdAt: createdAt(),
}, (t) => [
  primaryKey({ columns: [t.provider, t.entityType, t.externalId] }),
  index('external_ids_entity').on(t.entityType, t.entityId),
])

/** Stored images. The original is kept; sized WebP renditions are derived on demand. */
export const assets = pgTable('assets', {
  id: id(),
  /** cover | artist | embedded */
  kind: text('kind').notNull(),
  /** Where it came from: a URL, or `file:<media_file id>`. */
  source: text('source').notNull(),
  /**
   * ready: the image is stored locally. remote: it lives at `remote_url` and is fetched
   * the first time someone asks for it. failed: the last fetch did not produce an image.
   * missing: the stored file is gone and could not be rebuilt from its source.
   * The columns that describe stored bytes are null until an asset is ready.
   */
  status: text('status').$type<'ready' | 'remote' | 'failed' | 'missing'>().notNull().default('ready'),
  remoteUrl: text('remote_url'),
  /** When a remote image was last fetched or last failed, or the asset was last found missing or rebuilt. */
  checkedAt: at('checked_at'),
  sha256: text('sha256'),
  mime: text('mime'),
  width: integer('width'),
  height: integer('height'),
  bytes: integer('bytes'),
  /** Dominant color, #rrggbb. */
  color: text('color'),
  thumbhash: text('thumbhash'),
  /** Path relative to the data directory. */
  storagePath: text('storage_path'),
  createdAt: createdAt(),
}, (t) => [
  // Local images are content addressed. A remote image may turn out to hold the same
  // bytes as another row, so it is left out of the uniqueness rule.
  uniqueIndex('assets_sha256').on(t.sha256).where(sql`${t.remoteUrl} is null`),
  uniqueIndex('assets_remote_url').on(t.remoteUrl),
])

export const lyrics = pgTable('lyrics', {
  recordingId: uuid('recording_id').primaryKey().references(() => recordings.id, { onDelete: 'cascade' }),
  synced: text('synced'),
  plain: text('plain'),
  instrumental: boolean('instrumental').notNull().default(false),
  /** embedded | sidecar | lrclib | none (looked up, nothing found) */
  source: text('source').notNull(),
  language: text('language'),
  fetchedAt: at('fetched_at').notNull().defaultNow(),
})

// ---------------------------------------------------------------------------
// Library: files on disk and everything derived from them.
// ---------------------------------------------------------------------------

export const libraryRoots = pgTable('library_roots', {
  id: id(),
  name: text('name').notNull(),
  path: text('path').notNull(),
  mode: text('mode').$type<LibraryRootMode>().notNull().default('read_only'),
  /** Path template for managed roots; null means the default template. */
  template: text('template'),
  enabled: boolean('enabled').notNull().default(true),
  watch: boolean('watch').notNull().default(true),
  lastScanStartedAt: at('last_scan_started_at'),
  lastScanFinishedAt: at('last_scan_finished_at'),
  lastScanStats: jsonb('last_scan_stats').$type<Record<string, number>>(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [uniqueIndex('library_roots_path').on(t.path)])

export const mediaFiles = pgTable('media_files', {
  id: id(),
  rootId: uuid('root_id').notNull().references(() => libraryRoots.id, { onDelete: 'cascade' }),
  /** Path relative to the root, with forward slashes. */
  relPath: text('rel_path').notNull(),
  size: bigint('size', { mode: 'number' }).notNull(),
  mtime: at('mtime').notNull(),
  /**
   * SHA-256 of the audio stream's packets, computed without decoding. Stable across
   * retagging and moves; this is the file's identity.
   */
  audioHash: text('audio_hash'),
  container: text('container').notNull(),
  codec: text('codec').notNull(),
  lossless: boolean('lossless').notNull().default(false),
  bitrate: integer('bitrate'),
  sampleRate: integer('sample_rate'),
  bitDepth: smallint('bit_depth'),
  channels: smallint('channels'),
  durationMs: integer('duration_ms').notNull().default(0),
  tags: jsonb('tags').$type<FileTags>().notNull().default({}),
  embeddedArtAssetId: uuid('embedded_art_asset_id'),
  // Measured loudness (EBU R128). Null until the loudness job has run.
  loudnessLufs: real('loudness_lufs'),
  truePeakDb: real('true_peak_db'),
  // ReplayGain values read from the file's own tags, when present.
  tagTrackGainDb: real('tag_track_gain_db'),
  tagTrackPeak: real('tag_track_peak'),
  tagAlbumGainDb: real('tag_album_gain_db'),
  tagAlbumPeak: real('tag_album_peak'),
  // Chromaprint fingerprint and the AcoustID it resolved to.
  fingerprint: text('fingerprint'),
  acoustid: text('acoustid'),
  /** Files with the same group key are treated as one album during matching. */
  groupKey: text('group_key'),
  // What the file is. `recording_id` is what makes a track playable.
  recordingId: uuid('recording_id').references(() => recordings.id, { onDelete: 'set null' }),
  releaseTrackId: uuid('release_track_id').references(() => releaseTracks.id, { onDelete: 'set null' }),
  releaseId: uuid('release_id').references(() => releases.id, { onDelete: 'set null' }),
  albumId: uuid('album_id').references(() => albums.id, { onDelete: 'set null' }),
  matchStatus: text('match_status').$type<MatchStatus>().notNull().default('pending'),
  /** Set by "Fix match". Rescans never change a locked file's links. */
  matchLocked: boolean('match_locked').notNull().default(false),
  matchConfidence: real('match_confidence'),
  matchSource: text('match_source').$type<MatchSource>(),
  /** scan | upload | inbox | provider:<provider id> */
  source: text('source').notNull().default('scan'),
  importId: uuid('import_id'),
  /** 0 discovered, 1 tags read (playable), 2 audio hash and loudness done. */
  probeStage: smallint('probe_stage').notNull().default(0),
  /**
   * Why the last probe or analysis of this file failed. Set instead of retrying; a scan
   * clears it when the file's size or mtime changes.
   */
  probeError: text('probe_error'),
  /** Set when a scan no longer finds the file. Cleared if it returns. */
  missingSince: at('missing_since'),
  addedAt: at('added_at').notNull().defaultNow(),
  updatedAt: updatedAt(),
}, (t) => [
  uniqueIndex('media_files_path').on(t.rootId, t.relPath),
  // Byte order, so a scan can merge a sorted directory walk with the rows page by page.
  index('media_files_scan_order').on(t.rootId, sql`${t.relPath} collate "C"`),
  index('media_files_audio_hash').on(t.audioHash),
  index('media_files_release_track').on(t.releaseTrackId),
  index('media_files_recording').on(t.recordingId),
  index('media_files_album').on(t.albumId),
  index('media_files_release').on(t.releaseId),
  index('media_files_group').on(t.rootId, t.groupKey),
  index('media_files_match_status').on(t.matchStatus),
  index('media_files_added').on(t.addedAt),
  // Present files only: ownership checks and the "recently added" walks.
  index('media_files_present_recent').on(t.addedAt, t.id).where(sql`${t.missingSince} is null`),
  index('media_files_present_album').on(t.albumId, t.addedAt, t.id).where(sql`${t.missingSince} is null`),
  index('media_files_present_recording').on(t.recordingId, t.addedAt, t.id).where(sql`${t.missingSince} is null`),
  index('media_files_import').on(t.importId),
])

/** Album loudness, measured across the owned files of one release. */
export const releaseLoudness = pgTable('release_loudness', {
  releaseId: uuid('release_id').primaryKey().references(() => releases.id, { onDelete: 'cascade' }),
  loudnessLufs: real('loudness_lufs').notNull(),
  truePeakDb: real('true_peak_db').notNull(),
  fileCount: integer('file_count').notNull(),
  computedAt: at('computed_at').notNull().defaultNow(),
})

/** Albums whose best match scored below the auto-accept threshold. */
export const matchReviews = pgTable('match_reviews', {
  id: id(),
  rootId: uuid('root_id').notNull().references(() => libraryRoots.id, { onDelete: 'cascade' }),
  groupKey: text('group_key').notNull(),
  /** What the files say: { artist, album, year, trackCount, folder }. */
  summary: jsonb('summary').$type<Record<string, unknown>>().notNull(),
  /** Ranked candidate releases with score breakdowns. */
  candidates: jsonb('candidates').$type<unknown[]>().notNull().default([]),
  /** open | resolved | dismissed */
  status: text('status').notNull().default('open'),
  resolvedBy: uuid('resolved_by').references(() => users.id, { onDelete: 'set null' }),
  resolvedAt: at('resolved_at'),
  createdAt: createdAt(),
}, (t) => [
  uniqueIndex('match_reviews_group').on(t.rootId, t.groupKey),
  index('match_reviews_status').on(t.status),
])

/** One "organize" run over a managed root: a set of planned moves applied together. */
export const organizeBatches = pgTable('organize_batches', {
  id: id(),
  rootId: uuid('root_id').notNull().references(() => libraryRoots.id, { onDelete: 'cascade' }),
  createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
  /** planned | applying | applied | reverting | reverted | failed */
  status: text('status').notNull().default('planned'),
  options: jsonb('options').$type<Record<string, unknown>>().notNull().default({}),
  stats: jsonb('stats').$type<Record<string, number>>(),
  createdAt: createdAt(),
  appliedAt: at('applied_at'),
  revertedAt: at('reverted_at'),
})

/** The undo journal. One row per file or sidecar moved by an organize batch. */
export const fileMoves = pgTable('file_moves', {
  id: id(),
  batchId: uuid('batch_id').notNull().references(() => organizeBatches.id, { onDelete: 'cascade' }),
  /** Null for sidecars (covers, .lrc, .cue). */
  fileId: uuid('file_id'),
  /** audio | sidecar */
  kind: text('kind').notNull().default('audio'),
  fromRelPath: text('from_rel_path').notNull(),
  toRelPath: text('to_rel_path').notNull(),
  /** planned | applied | reverted | failed | skipped */
  status: text('status').notNull().default('planned'),
  error: text('error'),
  appliedAt: at('applied_at'),
  revertedAt: at('reverted_at'),
}, (t) => [index('file_moves_batch').on(t.batchId)])

/** Index of the on-disk transcode cache. */
export const transcodes = pgTable('transcodes', {
  id: id(),
  fileId: uuid('file_id').notNull().references(() => mediaFiles.id, { onDelete: 'cascade' }),
  profile: text('profile').notNull(),
  storagePath: text('storage_path').notNull(),
  bytes: bigint('bytes', { mode: 'number' }).notNull().default(0),
  /** pending | ready | failed */
  status: text('status').notNull().default('pending'),
  error: text('error'),
  createdAt: createdAt(),
  lastUsedAt: at('last_used_at').notNull().defaultNow(),
}, (t) => [uniqueIndex('transcodes_file_profile').on(t.fileId, t.profile)])

/** A batch of files entering the library: a web upload, an inbox drop, or a provider delivery. */
export const imports = pgTable('imports', {
  id: id(),
  /** upload | inbox | acquisition */
  kind: text('kind').$type<ImportKind>().notNull(),
  /** What imported files get in `media_files.source`: upload | inbox | provider:<provider id> */
  source: text('source').notNull(),
  userId: uuid('user_id').references(() => users.id, { onDelete: 'set null' }),
  acquisitionJobId: uuid('acquisition_job_id'),
  targetRootId: uuid('target_root_id').references(() => libraryRoots.id, { onDelete: 'set null' }),
  /** receiving | processing | completed | failed */
  status: text('status').$type<ImportStatus>().notNull().default('receiving'),
  /** extracting | moving | identifying | filing while processing, else null. */
  step: text('step').$type<ImportStep>(),
  stepStartedAt: at('step_started_at'),
  /**
   * When identification decided which of the import's files are duplicates and removed them.
   * Until then automatic matching leaves the import's files alone (`matching/match.ts`).
   */
  duplicatesDecidedAt: at('duplicates_decided_at'),
  /** The inbox item's name, or what the uploader called it. */
  label: text('label'),
  /** Directory under the data directory holding the files until they are filed. */
  stagingPath: text('staging_path').notNull(),
  receivedFiles: integer('received_files').notNull().default(0),
  receivedBytes: bigint('received_bytes', { mode: 'number' }).notNull().default(0),
  stats: jsonb('stats').$type<Record<string, number>>(),
  /** Bookkeeping that lets processing resume after a crash (archive targets, the organize batch). */
  work: jsonb('work').$type<Record<string, unknown>>(),
  error: text('error'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  completedAt: at('completed_at'),
}, (t) => [
  index('imports_status').on(t.status, t.updatedAt),
  index('imports_user').on(t.userId, t.id),
])

// ---------------------------------------------------------------------------
// Per-user data. All of it points at catalog rows, never at files.
// ---------------------------------------------------------------------------

export const playbackSessions = pgTable('playback_sessions', {
  userId: uuid('user_id').primaryKey().references(() => users.id, { onDelete: 'cascade' }),
  /** The reducer's whole state: SessionState, SessionQueue and its serial counter. */
  state: jsonb('state').$type<unknown>().notNull(),
  version: bigint('version', { mode: 'number' }).notNull().default(0),
  queueVersion: bigint('queue_version', { mode: 'number' }).notNull().default(0),
  updatedAt: updatedAt(),
})

export const likes = pgTable('likes', {
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  entityType: text('entity_type').$type<LikeEntityType>().notNull(),
  entityId: uuid('entity_id').notNull(),
  createdAt: createdAt(),
}, (t) => [
  primaryKey({ columns: [t.userId, t.entityType, t.entityId] }),
  index('likes_user_recent').on(t.userId, t.entityType, t.createdAt),
])

/** 1..5 stars. Exists for Subsonic clients. */
export const ratings = pgTable('ratings', {
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  entityType: text('entity_type').$type<LikeEntityType>().notNull(),
  entityId: uuid('entity_id').notNull(),
  rating: smallint('rating').notNull(),
  updatedAt: updatedAt(),
}, (t) => [primaryKey({ columns: [t.userId, t.entityType, t.entityId] })])

export const playlists = pgTable('playlists', {
  id: id(),
  ownerId: uuid('owner_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  description: text('description'),
  isPublic: boolean('is_public').notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [index('playlists_owner').on(t.ownerId)])

export const playlistItems = pgTable('playlist_items', {
  id: id(),
  playlistId: uuid('playlist_id').notNull().references(() => playlists.id, { onDelete: 'cascade' }),
  /** Dense 0-based order within the playlist. */
  position: integer('position').notNull(),
  recordingId: uuid('recording_id').notNull().references(() => recordings.id, { onDelete: 'cascade' }),
  /** Album the track was added from; decides its artwork. */
  albumId: uuid('album_id').references(() => albums.id, { onDelete: 'set null' }),
  addedBy: uuid('added_by').references(() => users.id, { onDelete: 'set null' }),
  addedAt: at('added_at').notNull().defaultNow(),
}, (t) => [index('playlist_items_order').on(t.playlistId, t.position)])

export const plays = pgTable('plays', {
  id: id(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  recordingId: uuid('recording_id').notNull().references(() => recordings.id, { onDelete: 'cascade' }),
  albumId: uuid('album_id').references(() => albums.id, { onDelete: 'set null' }),
  deviceId: text('device_id'),
  /** app | subsonic */
  client: text('client').notNull().default('app'),
  startedAt: at('started_at').notNull().defaultNow(),
  msPlayed: integer('ms_played').notNull().default(0),
  /** True once the play passed the scrobble threshold (half the track or four minutes). */
  completed: boolean('completed').notNull().default(false),
}, (t) => [
  index('plays_user_recent').on(t.userId, t.startedAt),
  index('plays_recording').on(t.recordingId),
])

/** Outbound scrobbles, one row per play and target, retried until sent. */
export const scrobbleDeliveries = pgTable('scrobble_deliveries', {
  playId: uuid('play_id').notNull().references(() => plays.id, { onDelete: 'cascade' }),
  /** listenbrainz | lastfm */
  target: text('target').notNull(),
  /** pending | sent | failed */
  status: text('status').notNull().default('pending'),
  attempts: integer('attempts').notNull().default(0),
  lastError: text('last_error'),
  updatedAt: updatedAt(),
}, (t) => [
  primaryKey({ columns: [t.playId, t.target] }),
  index('scrobble_deliveries_status').on(t.status),
])

export const wants = pgTable('wants', {
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  entityType: text('entity_type').$type<'album' | 'recording'>().notNull(),
  entityId: uuid('entity_id').notNull(),
  createdAt: createdAt(),
  fulfilledAt: at('fulfilled_at'),
}, (t) => [primaryKey({ columns: [t.userId, t.entityType, t.entityId] })])

// ---------------------------------------------------------------------------
// Acquisition providers: external services that can supply missing music.
// ---------------------------------------------------------------------------

export const acquisitionProviders = pgTable('acquisition_providers', {
  id: id(),
  name: text('name').notNull(),
  baseUrl: text('base_url').notNull(),
  secretEncrypted: text('secret_encrypted').notNull(),
  enabled: boolean('enabled').notNull().default(true),
  /** assume_available | must_resolve */
  coverage: text('coverage').notNull().default('must_resolve'),
  priority: integer('priority').notNull().default(0),
  capabilities: jsonb('capabilities').$type<Record<string, unknown>>(),
  lastOkAt: at('last_ok_at'),
  lastError: text('last_error'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
})

export const acquisitionJobs = pgTable('acquisition_jobs', {
  id: id(),
  providerId: uuid('provider_id').notNull().references(() => acquisitionProviders.id, { onDelete: 'cascade' }),
  requestedBy: uuid('requested_by').references(() => users.id, { onDelete: 'set null' }),
  recordingId: uuid('recording_id').references(() => recordings.id, { onDelete: 'set null' }),
  albumId: uuid('album_id').references(() => albums.id, { onDelete: 'set null' }),
  offer: jsonb('offer').$type<Record<string, unknown>>(),
  /**
   * The recordings the job is for: the requested one, or an album's tracks that were not
   * owned when it was requested. A delivery is checked against these.
   */
  recordingIds: uuid('recording_ids').array().notNull().default(sql`'{}'::uuid[]`),
  /** resolving | queued | downloading | importing | completed | failed | rejected */
  status: text('status').notNull().default('resolving'),
  error: text('error'),
  /** Collapses duplicate requests for the same target (two devices pressing play). */
  idempotencyKey: text('idempotency_key').notNull(),
  providerJobId: text('provider_job_id'),
  /** SHA-256 of the job-scoped token the provider uses to deliver files. */
  uploadTokenHash: text('upload_token_hash'),
  importId: uuid('import_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  completedAt: at('completed_at'),
}, (t) => [
  uniqueIndex('acquisition_jobs_idempotency').on(t.idempotencyKey),
  index('acquisition_jobs_recording').on(t.recordingId),
  index('acquisition_jobs_status').on(t.status),
])

/**
 * Positive resolve cache: free offers a `must_resolve` provider returned for a recording.
 * A recording with a recent row here is on demand from that provider.
 */
export const acquisitionOffers = pgTable('acquisition_offers', {
  providerId: uuid('provider_id').notNull().references(() => acquisitionProviders.id, { onDelete: 'cascade' }),
  recordingId: uuid('recording_id').notNull().references(() => recordings.id, { onDelete: 'cascade' }),
  /** ProviderOffer[] from @squirmy/contracts, priced offers left out. */
  offers: jsonb('offers').$type<unknown[]>().notNull(),
  resolvedAt: at('resolved_at').notNull().defaultNow(),
}, (t) => [
  primaryKey({ columns: [t.providerId, t.recordingId] }),
  index('acquisition_offers_recording').on(t.recordingId),
])

/** Negative cache: things a provider could not supply, so they go back to gray. */
export const acquisitionMisses = pgTable('acquisition_misses', {
  providerId: uuid('provider_id').notNull().references(() => acquisitionProviders.id, { onDelete: 'cascade' }),
  entityType: text('entity_type').$type<'album' | 'recording'>().notNull(),
  entityId: uuid('entity_id').notNull(),
  reason: text('reason'),
  createdAt: createdAt(),
}, (t) => [
  primaryKey({ columns: [t.providerId, t.entityType, t.entityId] }),
  index('acquisition_misses_entity').on(t.entityId),
])

// ---------------------------------------------------------------------------
// Infrastructure
// ---------------------------------------------------------------------------

/** Responses from external metadata services. */
export const httpCache = pgTable('http_cache', {
  /** SHA-256 of provider + method + URL. */
  key: text('key').primaryKey(),
  provider: text('provider').notNull(),
  url: text('url').notNull(),
  status: integer('status').notNull(),
  body: text('body').notNull(),
  fetchedAt: at('fetched_at').notNull().defaultNow(),
  expiresAt: at('expires_at').notNull(),
}, (t) => [index('http_cache_expires').on(t.expiresAt)])

/** Cross-process rate limiting: the next time a caller may hit `key`. */
export const rateLimits = pgTable('rate_limits', {
  key: text('key').primaryKey(),
  nextAt: at('next_at').notNull().defaultNow(),
})

export type CatalogIndexKind = 'artist' | 'album' | 'recording'
export type CatalogIndexImportState = 'running' | 'active' | 'failed' | 'cancelled' | 'replaced' | 'dropped'
export type CatalogIndexImportPhase = 'download' | 'build' | 'swap'

/**
 * Optional local search index loaded from MusicBrainz canonical dumps. Empty unless
 * the operator runs the importer, which builds a replacement table and swaps it in
 * (modules/catalog-index/import.ts), so the DDL there must match this definition.
 * Rows are written once, in descending `score` order within each kind, and never
 * updated; search relies on that physical order. There is no primary key: nothing
 * looks rows up by id, and at tens of millions of rows the index would cost gigabytes.
 * See docs/local-search-index.md for the design and its measurements.
 */
export const catalogIndex = pgTable('catalog_index', {
  kind: text('kind').$type<CatalogIndexKind>().notNull(),
  /** Artist, release group or recording MBID. */
  mbid: uuid('mbid').notNull(),
  name: text('name').notNull(),
  artistName: text('artist_name'),
  albumName: text('album_name'),
  nameKey: text('name_key').notNull(),
  /** Popularity prior from 0 to 1. */
  score: real('score').notNull(),
  /** Among the most popular rows of its kind; only these carry the fuzzy trigram index. */
  head: boolean('head').notNull(),
}, (t) => [
  index('catalog_index_artist_head').using('gin', t.nameKey.op('gin_trgm_ops')).where(sql`kind = 'artist' and head`),
  index('catalog_index_album_head').using('gin', t.nameKey.op('gin_trgm_ops')).where(sql`kind = 'album' and head`),
  index('catalog_index_recording_head').using('gin', t.nameKey.op('gin_trgm_ops')).where(sql`kind = 'recording' and head`),
  index('catalog_index_prefix').on(t.kind, sql`(${t.nameKey} collate "C")`),
])

/**
 * One row per import of the local search index. The row in state `active` describes
 * the index currently in `catalog_index`; at most one row is `running`.
 */
export const catalogIndexImports = pgTable('catalog_index_imports', {
  id: id(),
  state: text('state').$type<CatalogIndexImportState>().notNull(),
  phase: text('phase').$type<CatalogIndexImportPhase>(),
  source: text('source'),
  /** When MetaBrainz produced the dump, from its TIMESTAMP file. */
  dumpDate: at('dump_date'),
  /** Size knob: keep at most this many recordings per artist credit; null keeps all. */
  recordingsPerArtist: integer('recordings_per_artist'),
  bytesRead: bigint('bytes_read', { mode: 'number' }).notNull().default(0),
  totalBytes: bigint('total_bytes', { mode: 'number' }),
  rowsRead: bigint('rows_read', { mode: 'number' }).notNull().default(0),
  artists: integer('artists'),
  albums: integer('albums'),
  recordings: integer('recordings'),
  error: text('error'),
  cancelRequested: boolean('cancel_requested').notNull().default(false),
  startedAt: at('started_at').notNull().defaultNow(),
  finishedAt: at('finished_at'),
}, (t) => [index('catalog_index_imports_state').on(t.state)])
